const data = $json.body;

return [{
  json: {
    departureLocation: data.departureLocation || "Not provided",
    destination: data.destination || "Not specified",
    budget: data.budget || "~",
    tripType: data.tripType || "N/A",
    groupSize: data.groupSize || "1",
    ageRange: data.ageRange || "~",
    startDate: data.startDate || "N/A",
    endDate: data.endDate || "N/A",
    email: data.email || "unknown",
    display: String(data.display || "false").toLowerCase()
  }
}];

const {
  destination,
  customDestination,
  startDate,
  endDate,
  budget,
  tripType,
  groupSize,
  ageRange,
  email,
  departureLocation,
  display // Add display here
} = $json;

const finalDestination = customDestination || destination;

const prompt = `You are a helpful travel agent. A user is planning a trip and needs your help creating a detailed itinerary.\n\n- Departure location: ${departureLocation || "Not provided"}\n- Destination: ${finalDestination}\n- Travel dates: ${startDate} to ${endDate}\n- Budget: $${budget}\n- Trip type: ${tripType}\n- Group size: ${groupSize}\n- Age ranges: ${Array.isArray(ageRange) ? ageRange.join(", ") : ageRange || "not specified"}\n\nCreate a complete itinerary for this trip...`;

return [{
  json: {
    departureLocation,
    destination: finalDestination,
    startDate,
    endDate,
    budget,
    tripType,
    groupSize,
    ageRange,
    email,
    display, // Include display in the output
    prompt
  }
}];

const travel = $node["Prepare Travel Data"].json;
const ai = $node["OpenAI"].json.message?.content || "No itinerary found.";
const displayValue = String(travel.display); // Use travel.display instead of $json.display
console.log('Display value before If node:', displayValue);
return [
  {
    json: {
      destination: travel.destination,
      departureLocation: travel.departureLocation,
      startDate: travel.startDate,
      endDate: travel.endDate,
      groupSize: travel.groupSize,
      budget: travel.budget,
      email: travel.email,
      itinerary: ai,
      display: displayValue
    }
  }
];

// Access input data (if needed) from the previous node
const inputData = $input.first().json || {};

